def read_seed(body):
    if not body.startswith(b'\xff\xd8') or not body.endswith(b'\xff\xd9'):raise ValueError('Not JPEG')
    position=2;seed=None
    while position<len(body)-2:
        if body[position]!=255:raise ValueError('Bad marker')
        marker=body[position+1]
        if marker in (0xDA,0xD9):break
        length=int.from_bytes(body[position+2:position+4],'big')
        if length<2 or position+2+length>len(body):raise ValueError('Bad length')
        payload=body[position+4:position+2+length]
        if marker==0xED and payload.startswith(b'METAWEB-APP13\0'):
            seed=dict(line.split('=',1) for line in payload[13:].decode().splitlines() if '=' in line)
        position+=2+length
    if seed is None or seed.get('SHA256')!='1f296bb3da9dc1f48dce3ddd2289cde36766226154f1e6f5eb4e1eded2832bac' or seed.get('TITLE')!='vojtamaur-web-export-metaweb-2026-10-22_09-03-12-113251.epub':raise ValueError('Missing/altered seed')
    return seed
